  function wireModalSiteOrRegionMap(hostEl, formType, SEED) {
    if (!hostEl) return;
    hydrateSeedGeo(SEED);
    if (formType === 'site') {
      _wireSiteInteractiveMapCore(hostEl, SEED, _sitePickerCfgForModal(hostEl));
      return;
    }
    if (formType === 'region') {
      const canvas = hostEl.querySelector('#modalRegionMapCanvas');
      if (!canvas) return;
      if (canvas.dataset.geoWired === '1') {
        if (canvas._leafletMap) {
          setTimeout(() => {
            try {
              canvas._leafletMap.invalidateSize();
              if (typeof canvas._hydrateRegionOverlay === 'function') canvas._hydrateRegionOverlay();
            } catch (_) {}
          }, 40);
        }
        return;
      }
      cleanupModalGeoMap();
      canvas.dataset.geoWired = '1';
      const regionAbort = new AbortController();
      let regionMapRef = null;
      let polyPts = [];
      let polyLocked = false;
      let activeBoundaryItem = null;
      let previewLine = null;
      let redrawMapLayers = null;
      let convertingBoundaryToPoly = false;
      _activeModalPreMountCancel = () => {
        regionAbort.abort();
        delete canvas.dataset.geoWired;
        delete canvas._hydrateRegionOverlay;
        regionMapRef = null;
      };
      _activeModalCleanup = () => {
        if (previewLine && regionMapRef) {
          try { regionMapRef.removeLayer(previewLine); } catch (_) {}
          previewLine = null;
        }
      };

      const regNameWrap = hostEl.querySelector('#wrap_f_region_name');
      const regNameInp = hostEl.querySelector('#f_region');
      const regLockPill = hostEl.querySelector('#f_region_lock_pill');
      const mapSearchWrap = hostEl.querySelector('#wrap_f_map_region_search');
      const mapSearchInp = hostEl.querySelector('#f_map_region_search');
      const corridorSel = hostEl.querySelector('#f_corridor');
      const corridorDispInp = hostEl.querySelector('#f_corridor_display');
      const corridorWrap = hostEl.querySelector('#wrap_f_corridor');
      if (corridorDispInp) {
        corridorDispInp.readOnly = true;
        corridorDispInp.addEventListener('mousedown', ev => { ev.preventDefault(); });
        corridorDispInp.addEventListener('focus', () => { try { corridorDispInp.blur(); } catch (_) {} });
      }
      const shapeSel = hostEl.querySelector('#f_zone_type');
      const radWrap = hostEl.querySelector('#wrap_f_radius_km');
      const radInp = hostEl.querySelector('#f_radius_km');
      const radSlider = hostEl.querySelector('#modalCircleRadiusSlider');
      const autoCodeInp = hostEl.querySelector('#f_auto_code');
      const cLatInp = hostEl.querySelector('#f_center_lat');
      const cLngInp = hostEl.querySelector('#f_center_lng');
      const gjInp = hostEl.querySelector('#f_zone_geojson');
      const distInp = hostEl.querySelector('#f_distance_km');
      const statusEl = hostEl.querySelector('#modalRegionZoneHint');
      const insidePill = hostEl.querySelector('#modalRegionLiveInsidePill');
      const quickStrip = hostEl.querySelector('#modalRegionQuickStrip');
      const editCornersBtn = hostEl.querySelector('#modalRegionEditCornersBtn');
      const undoBtn = hostEl.querySelector('#modalPolyUndoBtn');
      const finishBtn = hostEl.querySelector('#modalPolyFinishBtn');
      const clearBtn = hostEl.querySelector('#modalRegionClearPtsBtn');
      const editRegRec = (typeof window !== 'undefined' && typeof window.MFG_GET_EDITING_MODAL_RECORD === 'function')
        ? window.MFG_GET_EDITING_MODAL_RECORD('regions')
        : ((typeof window !== 'undefined' && window.STATE && window.STATE.editingRecord && window.STATE.editingRecord.crKey === 'regions') ? window.STATE.editingRecord : null);
      const canEditRegionShape = canAccessGeoIndustryNow(getGeoActiveIndustry()) && (editRegRec ? canShapeRegionsNow() : canEnterRegionNow());
      let mapSearchCtl = null;

      const setSelectValAndSync = (selEl, val) => {
        if (!selEl) return;
        selEl.value = val;
        selEl.dispatchEvent(new Event('change', { bubbles: true }));
      };

      const setFrozenRegionValue = (val, markFromSearch = true) => {
        if (!regNameInp) return;
        const cleanVal = String(val || '').trim();
        regNameInp.value = cleanVal;
        if (markFromSearch) regNameInp.dataset.fromMapSearch = cleanVal ? '1' : '0';
        if (regNameWrap) regNameWrap.classList.toggle('has-gov-val', Boolean(cleanVal && regNameInp.readOnly));
        regNameInp.dispatchEvent(new Event('input', { bubbles: true }));
        regNameInp.dispatchEvent(new Event('change', { bubbles: true }));
      };

      const syncRegionModeFields = () => {
        const zt = (shapeSel && shapeSel.value) || 'boundary';
        const isBoundary = zt === 'boundary';
        if (mapSearchWrap) mapSearchWrap.hidden = !isBoundary;
        if (corridorWrap) corridorWrap.hidden = !isBoundary;
        if (!canEditRegionShape) {
          if (regLockPill) regLockPill.hidden = true;
          if (regNameInp && canModifyRecordNow()) {
            regNameInp.readOnly = false;
            regNameInp.removeAttribute('readonly');
            regNameInp.removeAttribute('tabindex');
            regNameInp.setAttribute('aria-readonly', 'false');
            if (regNameWrap) {
              regNameWrap.classList.remove('is-policy-locked', 'is-geo-frozen-field', 'has-gov-val');
            }
          }
          return;
        }
        if (regNameInp) {
          if (isBoundary) {
            regNameInp.readOnly = true;
            regNameInp.setAttribute('readonly', 'readonly');
            regNameInp.setAttribute('tabindex', '-1');
            regNameInp.setAttribute('aria-readonly', 'true');
            regNameInp.placeholder = 'Locked to Search Map Region...';
            if (regLockPill) regLockPill.hidden = false;
            if (regNameWrap) {
              regNameWrap.classList.add('is-policy-locked', 'is-geo-frozen-field');
              regNameWrap.classList.toggle('has-gov-val', Boolean(regNameInp.value && regNameInp.value.trim()));
            }
          } else {
            regNameInp.readOnly = false;
            regNameInp.removeAttribute('readonly');
            regNameInp.removeAttribute('tabindex');
            regNameInp.setAttribute('aria-readonly', 'false');
            regNameInp.placeholder = 'Type custom region name (e.g. Fanar)...';
            if (regLockPill) regLockPill.hidden = true;
            if (regNameWrap) {
              regNameWrap.classList.remove('is-policy-locked', 'is-geo-frozen-field', 'has-gov-val');
            }
          }
        }
      };

      if (regNameInp) {
        regNameInp.addEventListener('mousedown', ev => {
          if (!canEditRegionShape) return;
          const ztNow = (shapeSel && shapeSel.value) || 'boundary';
          if (ztNow === 'boundary') {
            ev.preventDefault();
            if (mapSearchInp && (!mapSearchWrap || !mapSearchWrap.hidden)) {
              try { mapSearchInp.focus({ preventScroll: true }); } catch (_) { try { mapSearchInp.focus(); } catch (__) {} }
              if (mapSearchCtl && typeof mapSearchCtl.runQuery === 'function') {
                setTimeout(() => { try { mapSearchCtl.runQuery(true); } catch (_) {} }, 10);
              }
            }
          }
        });
        regNameInp.addEventListener('focus', () => {
          if (!canEditRegionShape) return;
          const ztNow = (shapeSel && shapeSel.value) || 'boundary';
          if (ztNow === 'boundary' && regNameInp.readOnly) {
            try { regNameInp.blur(); } catch (_) {}
          }
        });
        regNameInp.addEventListener('input', () => {
          const ztNow = (shapeSel && shapeSel.value) || 'boundary';
          if (ztNow !== 'boundary') {
            regNameInp.dataset.fromMapSearch = '0';
          } else if (regNameWrap) {
            regNameWrap.classList.toggle('has-gov-val', Boolean(regNameInp.value && regNameInp.value.trim()));
          }
        });
      }

      const setModalGovernorate = (codeVal) => {
        const cleanCode = String(codeVal || '').trim();
        const dispText = cleanCode ? corridorLabel(cleanCode) : '';
        if (corridorSel) corridorSel.value = cleanCode;
        if (corridorDispInp) corridorDispInp.value = dispText;
        if (corridorWrap) corridorWrap.classList.toggle('has-gov-val', Boolean(dispText));
      };

      const syncModalGovernorate = () => {
        const zt = (shapeSel && shapeSel.value) || 'boundary';
        if (zt !== 'boundary') {
          setModalGovernorate('');
          return;
        }
        if (activeBoundaryItem && activeBoundaryItem.corridor) {
          setModalGovernorate(activeBoundaryItem.corridor);
          return;
        }
        const parsedGj = gjInp && gjInp.value ? parseZoneGeoJson(gjInp.value) : null;
        const clat = cLatInp && cLatInp.value !== '' ? parseFloat(cLatInp.value) : null;
        const clng = cLngInp && cLngInp.value !== '' ? parseFloat(cLngInp.value) : null;
        if (parsedGj || (clat != null && clng != null && Number.isFinite(clat) && Number.isFinite(clng))) {
          const det = resolveGovernorate({ zoneType: 'boundary', geojson: parsedGj, lat: clat, lng: clng, name: (regNameInp && regNameInp.value) || '' }, SEED);
          setModalGovernorate(det.code);
          return;
        }
        const typedCandidate = ((mapSearchInp && mapSearchInp.value) || (regNameInp && regNameInp.value) || '').trim();
        const typedHit = typedCandidate ? findAtlasRegionByName(typedCandidate, SEED) : null;
        setModalGovernorate(typedHit && typedHit.corridor ? typedHit.corridor : '');
      };

      const countSitesInside = (gj, cLat, cLng, radKm, mode) => {
        let cnt = 0;
        const activeInd = getGeoActiveIndustry();
        ((SEED && SEED.records && SEED.records.sites) || []).forEach(s => {
          if (!isRowInGeoIndustry(s, activeInd) || s.latitude == null || s.longitude == null) return;
          const lat = Number(s.latitude), lng = Number(s.longitude);
          if (mode === 'circle' && cLat != null && cLng != null && radKm > 0) {
            if (pointInCircle(lat, lng, cLat, cLng, radKm)) cnt++;
          } else if (gj) {
            if (pointInGeoJson(lat, lng, gj)) cnt++;
          }
        });
        return cnt;
      };

      const commitPolyToHiddenFields = () => {
        const isMfg = getGeoActiveIndustry() === 'Manufacturing';
        if (polyPts.length >= 3) {
          const ring = polyPts.concat([[polyPts[0][0], polyPts[0][1]]]);
          if (gjInp) gjInp.value = JSON.stringify({ type: 'Polygon', coordinates: [ring] });
          const lats = ring.map(p => p[1]), lngs = ring.map(p => p[0]);
          const cLat = round5((Math.min(...lats) + Math.max(...lats)) / 2);
          const cLng = round5((Math.min(...lngs) + Math.max(...lngs)) / 2);
          if (cLatInp) cLatInp.value = String(cLat);
          if (cLngInp) cLngInp.value = String(cLng);
          if (isMfg && distInp) {
            const wtcHub = getCompanyHub('WTC', SEED);
            distInp.value = String(Math.round(roadAdjustedKm(wtcHub.lat, wtcHub.lng, cLat, cLng)));
          }
        } else {
          if (gjInp) gjInp.value = '';
        }
      };

      const syncToolbarAndStatus = () => {
        const zt = (shapeSel && shapeSel.value) || 'boundary';
        syncRegionModeFields();
        if (shapeSel) shapeSel.disabled = !canEditRegionShape;
        if (mapSearchInp) {
          mapSearchInp.disabled = !canEditRegionShape;
          mapSearchInp.readOnly = !canEditRegionShape;
        }
        if (radWrap) radWrap.hidden = zt !== 'circle';
        if (radInp) radInp.readOnly = !canEditRegionShape;
        if (distInp) {
          distInp.readOnly = !canEditRegionShape;
          distInp.disabled = !canEditRegionShape;
          distInp.classList.toggle('pa-locked-input', !canEditRegionShape);
        }
        if (radSlider) {
          radSlider.hidden = zt !== 'circle';
          radSlider.disabled = !canEditRegionShape;
        }
        if (quickStrip) quickStrip.hidden = !canEditRegionShape || zt !== 'boundary';
        if (undoBtn) {
          undoBtn.hidden = !canEditRegionShape || zt !== 'polygon' || polyPts.length === 0;
          undoBtn.disabled = !canEditRegionShape;
        }
        if (finishBtn) {
          finishBtn.hidden = !canEditRegionShape || zt !== 'polygon' || polyPts.length < 3;
          finishBtn.disabled = !canEditRegionShape;
          finishBtn.textContent = polyLocked ? 'Add Corners' : 'Finish Shape';
        }
        const parsedGj = gjInp && gjInp.value ? parseZoneGeoJson(gjInp.value) : null;
        if (editCornersBtn) {
          editCornersBtn.hidden = !canEditRegionShape || !(zt === 'boundary' && parsedGj);
          editCornersBtn.disabled = !canEditRegionShape;
        }
        if (clearBtn) {
          clearBtn.hidden = !canEditRegionShape;
          clearBtn.disabled = !canEditRegionShape;
        }
        hostEl.querySelectorAll('[data-pick-map-region]').forEach(ch => { ch.disabled = !canEditRegionShape; });

        const isCrosshair = canEditRegionShape && (zt === 'circle' || (zt === 'polygon' && !polyLocked));
        canvas.classList.toggle('is-drawing-zone', isCrosshair);

        if (zt === 'boundary') {
          if (parsedGj) {
            const clat = cLatInp && cLatInp.value ? parseFloat(cLatInp.value) : null;
            const clng = cLngInp && cLngInp.value ? parseFloat(cLngInp.value) : null;
            const cnt = countSitesInside(parsedGj, clat, clng, 0, 'boundary');
            const areaKm2 = round1(regionAreaKm2({ zone_type: 'boundary', zone_geojson: parsedGj }));
            const labelNm = (activeBoundaryItem && activeBoundaryItem.name) || (regNameInp && regNameInp.value) || 'Selected Region';
            if (statusEl) statusEl.textContent = `${labelNm} boundary loaded (${areaKm2} km²) · Click 'Adjust Corners' to customize`;
            if (insidePill) {
              insidePill.hidden = false;
              insidePill.textContent = `${cnt} ${cnt === 1 ? 'Site' : 'Sites'} inside`;
            }
          } else {
            if (statusEl) statusEl.textContent = 'Search a city or district above (e.g. Beirut, Saida, Metn) or pick a quick chip:';
            if (insidePill) insidePill.hidden = true;
          }
        } else if (zt === 'circle') {
          const clat = cLatInp && cLatInp.value ? parseFloat(cLatInp.value) : null;
          const clng = cLngInp && cLngInp.value ? parseFloat(cLngInp.value) : null;
          const rad = radInp && radInp.value ? Math.max(0.2, parseFloat(radInp.value) || 1.5) : 1.5;
          if (clat != null && clng != null && Number.isFinite(clat) && Number.isFinite(clng)) {
            const cnt = countSitesInside(null, clat, clng, rad, 'circle');
            if (statusEl) statusEl.textContent = `Circle radius ${round1(rad)} km · Drag center pin or slider to resize`;
            if (insidePill) {
              insidePill.hidden = false;
              insidePill.textContent = `${cnt} ${cnt === 1 ? 'Site' : 'Sites'} inside`;
            }
          } else {
            if (statusEl) statusEl.textContent = 'Click anywhere on the map to place the Circle center';
            if (insidePill) insidePill.hidden = true;
          }
        } else if (zt === 'polygon') {
          if (polyPts.length === 0) {
            if (statusEl) statusEl.textContent = 'Click on the map to place Corner 1 of your custom boundary';
            if (insidePill) insidePill.hidden = true;
          } else if (polyPts.length < 3) {
            if (statusEl) statusEl.textContent = `${polyPts.length} ${polyPts.length === 1 ? 'corner' : 'corners'} placed · Click ${3 - polyPts.length} more on the map`;
            if (insidePill) insidePill.hidden = true;
          } else {
            const ring = polyPts.concat([[polyPts[0][0], polyPts[0][1]]]);
            const gj = { type: 'Polygon', coordinates: [ring] };
            const cnt = countSitesInside(gj, null, null, 0, 'polygon');
            const areaKm2 = round1(approxRingAreaKm2(ring));
            if (statusEl) {
              statusEl.textContent = polyLocked
                ? `Boundary locked (${polyPts.length} corners · ${areaKm2} km²) · Drag any corner or midpoint to refine`
                : `${polyPts.length} corners (${areaKm2} km²) · Click green Corner 1 or 'Finish Shape' to lock`;
            }
            if (insidePill) {
              insidePill.hidden = false;
              insidePill.textContent = `${cnt} ${cnt === 1 ? 'Site' : 'Sites'} inside`;
            }
          }
        }
        syncModalGovernorate();
      };

      const redraw = (opts = {}) => {
        syncToolbarAndStatus();
        if (redrawMapLayers) redrawMapLayers(opts);
      };

      const applyPickedAtlasRegion = (hit) => {
        if (!hit || !canEditRegionShape) return;
        activeBoundaryItem = hit;
        if (shapeSel && shapeSel.value !== 'boundary') setSelectValAndSync(shapeSel, 'boundary');
        syncRegionModeFields();
        if (mapSearchInp) mapSearchInp.value = hit.name;
        setFrozenRegionValue(hit.name, true);
        if (autoCodeInp) autoCodeInp.value = hit.code || deriveRegionCode(hit.name);
        const detGov = resolveGovernorate({ zoneType: 'boundary', geojson: hit.geojson, lat: hit.lat, lng: hit.lng, corridor: hit.corridor, name: hit.name }, SEED);
        setModalGovernorate(detGov.code || hit.corridor || '');
        if (cLatInp) cLatInp.value = hit.lat != null ? String(hit.lat) : '';
        if (cLngInp) cLngInp.value = hit.lng != null ? String(hit.lng) : '';
        if (gjInp) gjInp.value = hit.geojson ? JSON.stringify(hit.geojson) : '';
        if (getGeoActiveIndustry() === 'Manufacturing' && distInp && hit.lat != null && hit.lng != null) {
          const wtcHub = getCompanyHub('WTC', SEED);
          distInp.value = String(Math.round(roadAdjustedKm(wtcHub.lat, wtcHub.lng, Number(hit.lat), Number(hit.lng))));
        }
        hostEl.querySelectorAll('[data-pick-map-region]').forEach(ch => {
          ch.classList.toggle('active', norm(ch.getAttribute('data-pick-map-region')) === norm(hit.name));
        });
        redraw({ fitBounds: true });
      };

      if (mapSearchInp) {
        mapSearchCtl = attachMapRegionSearchInput(mapSearchInp, {
          SEED,
          showPopularOnClick: true,
          decorateWithIcon: true,
          onSelectRegion: applyPickedAtlasRegion,
          onClear: () => {
            if (!canEditRegionShape) return;
            activeBoundaryItem = null;
            if (!shapeSel || shapeSel.value === 'boundary') {
              setFrozenRegionValue('', true);
              if (gjInp) gjInp.value = '';
              if (cLatInp) cLatInp.value = '';
              if (cLngInp) cLngInp.value = '';
            }
            hostEl.querySelectorAll('[data-pick-map-region]').forEach(ch => ch.classList.remove('active'));
            redraw();
          }
        });
        mapSearchInp.addEventListener('focus', () => {
          if (!canEditRegionShape) return;
          if (!shapeSel || shapeSel.value === 'boundary') {
            syncRegionModeFields();
            const q = String(mapSearchInp.value || '').trim();
            if (q && regNameInp && regNameInp.value !== q) {
              const hit = findAtlasRegionByName(q, SEED);
              setFrozenRegionValue(hit ? hit.name : q, true);
            }
          }
        });
        mapSearchInp.addEventListener('input', () => {
          if (!canEditRegionShape) return;
          if (!shapeSel || shapeSel.value === 'boundary') {
            const rawQ = String(mapSearchInp.value || '').trim();
            if (activeBoundaryItem && norm(rawQ) !== norm(activeBoundaryItem.name)) activeBoundaryItem = null;
            const hit = rawQ ? findAtlasRegionByName(rawQ, SEED) : null;
            setFrozenRegionValue(hit ? hit.name : rawQ, true);
            syncModalGovernorate();
          }
        });
      }
      hostEl.querySelectorAll('[data-pick-map-region]').forEach(chip => {
        chip.addEventListener('click', () => {
          if (!canEditRegionShape) return;
          const hit = findAtlasRegionByName(chip.getAttribute('data-pick-map-region'), SEED);
          if (hit) applyPickedAtlasRegion(hit);
        });
      });
      if (shapeSel) {
        shapeSel.addEventListener('change', () => {
          if (!canEditRegionShape) return;
          closeAllGeoPlaceMenus();
          const zt = shapeSel.value || 'boundary';
          if (zt === 'circle' || zt === 'polygon') {
            if (convertingBoundaryToPoly && zt === 'polygon' && gjInp && gjInp.value) {
              polyPts = extractEditablePolyRing(gjInp.value, 20);
              polyLocked = polyPts.length >= 3;
            } else {
              if (regNameInp && regNameInp.dataset.fromMapSearch === '1') {
                setFrozenRegionValue('', false);
              }
              activeBoundaryItem = null;
              if (mapSearchInp) mapSearchInp.value = '';
              hostEl.querySelectorAll('[data-pick-map-region]').forEach(ch => ch.classList.remove('active'));
              if (zt === 'circle') {
                if (gjInp) gjInp.value = '';
              } else if (zt === 'polygon' && !convertingBoundaryToPoly) {
                if (polyPts.length === 0 && gjInp) gjInp.value = '';
              }
            }
          } else if (zt === 'boundary') {
            const searchQ = String((mapSearchInp && mapSearchInp.value) || '').trim();
            const hit = (activeBoundaryItem && activeBoundaryItem.name ? activeBoundaryItem : null) || (searchQ ? findAtlasRegionByName(searchQ, SEED) : null);
            setFrozenRegionValue(hit ? hit.name : searchQ, true);
          }
          convertingBoundaryToPoly = false;
          redraw();
        });
      }
      if (editCornersBtn) {
        editCornersBtn.addEventListener('click', () => {
          if (!canEditRegionShape) return;
          if (gjInp && gjInp.value) {
            convertingBoundaryToPoly = true;
            polyPts = extractEditablePolyRing(gjInp.value, 20);
            polyLocked = true;
            if (shapeSel) setSelectValAndSync(shapeSel, 'polygon');
            redraw({ fitBounds: true });
          }
        });
      }
      if (radInp) {
        radInp.addEventListener('input', () => {
          if (!canEditRegionShape) return;
          if (radSlider) radSlider.value = String(Math.min(25, Math.max(0.3, parseFloat(radInp.value) || 1.5)));
          redraw();
        });
      }
      if (radSlider) {
        radSlider.addEventListener('input', () => {
          if (!canEditRegionShape) return;
          const v = round1(parseFloat(radSlider.value) || 1.5);
          if (radInp) radInp.value = String(v);
          redraw();
        });
      }
      if (undoBtn) {
        undoBtn.addEventListener('click', () => {
          if (!canEditRegionShape) return;
          polyPts.pop();
          if (polyPts.length < 3) polyLocked = false;
          commitPolyToHiddenFields();
          redraw();
        });
      }
      if (finishBtn) {
        finishBtn.addEventListener('click', () => {
          if (!canEditRegionShape) return;
          if (polyPts.length >= 3) {
            polyLocked = !polyLocked;
            commitPolyToHiddenFields();
            redraw();
          }
        });
      }
      if (clearBtn) {
        clearBtn.addEventListener('click', () => {
          if (!canEditRegionShape) return;
          closeAllGeoPlaceMenus();
          polyPts = [];
          polyLocked = false;
          activeBoundaryItem = null;
          if (mapSearchInp) mapSearchInp.value = '';
          if (!shapeSel || shapeSel.value === 'boundary') {
            setFrozenRegionValue('', true);
          }
          if (gjInp) gjInp.value = '';
          if (cLatInp) cLatInp.value = '';
          if (cLngInp) cLngInp.value = '';
          hostEl.querySelectorAll('[data-pick-map-region]').forEach(ch => ch.classList.remove('active'));
          redraw();
        });
      }

      const hydrateRegionFieldsIntoMapState = () => {
        const zt = (shapeSel && shapeSel.value) || 'boundary';
        if (zt === 'polygon' && gjInp && gjInp.value) {
          polyPts = extractEditablePolyRing(gjInp.value, 24);
          polyLocked = polyPts.length >= 3;
        } else if (zt === 'boundary' && regNameInp && regNameInp.value) {
          activeBoundaryItem = findAtlasRegionByName(regNameInp.value, SEED) || null;
          regNameInp.dataset.fromMapSearch = '1';
        } else if (zt === 'circle' && radSlider && radInp && radInp.value !== '') {
          radSlider.value = String(Math.min(25, Math.max(0.3, parseFloat(radInp.value) || 1.5)));
        }
      };

      canvas._hydrateRegionOverlay = () => {
        hydrateRegionFieldsIntoMapState();
        redraw({ fitBounds: true });
      };

      hydrateRegionFieldsIntoMapState();
      syncToolbarAndStatus();

      ensureLeaflet().then(L => {
        if (!canvas.isConnected || regionAbort.signal.aborted || canvas.closest('[hidden]')) return;
        const map = L.map(canvas, { zoomControl: true, attributionControl: false, doubleClickZoom: false }).setView([33.85, 35.51], 10);
        regionMapRef = map;
        stripLeafletTitles(canvas);
        canvas._leafletMap = map;
        _activeModalMap = map;
        addBaseTiles(L, map);
        _mountInlinePickerFullWindow(L, map, canvas, {
          kind: 'modal',
          wrapSel: '#modalRegionMapWrap',
          barBtnSel: '#modalRegionToggleFullWinBtn',
          cornerBtnId: 'modalRegionCanvasFullWinBtn'
        });
        const lg = L.layerGroup().addTo(map);
        setTimeout(() => { try { map.invalidateSize(); } catch (_) {} }, 50);

        redrawMapLayers = (opts = {}) => {
          lg.clearLayers();
          if (previewLine) {
            try { map.removeLayer(previewLine); } catch (_) {}
            previewLine = null;
          }
          const zt = (shapeSel && shapeSel.value) || 'boundary';
          const parsedGj = gjInp && gjInp.value ? parseZoneGeoJson(gjInp.value) : null;
          const isCrosshair = canEditRegionShape && (zt === 'circle' || (zt === 'polygon' && !polyLocked));
          canvas.classList.toggle('is-drawing-zone', isCrosshair);

          const isMfg = getGeoActiveIndustry() === 'Manufacturing';
          if (isMfg) {
            getAllCompanyHubs(SEED).forEach(h => {
              L.marker([h.lat, h.lng], { icon: makeSvgPinIcon(L, '#D9A54A', h.name, true), interactive: false }).addTo(lg);
            });
          }

          if (zt === 'boundary') {
            if (parsedGj) {
              const bLayer = L.geoJSON(parsedGj, {
                style: { color: '#1D4ED8', fillColor: '#3B82F6', fillOpacity: 0.20, weight: 2.8 }
              }).addTo(lg);
              if (opts.fitBounds) {
                try {
                  const b = bLayer.getBounds();
                  if (b && b.isValid && b.isValid()) map.fitBounds(b, { padding: [22, 22], maxZoom: 13, animate: false });
                } catch (_) {}
              }
            }
          } else if (zt === 'circle') {
            const clat = cLatInp && cLatInp.value ? parseFloat(cLatInp.value) : null;
            const clng = cLngInp && cLngInp.value ? parseFloat(cLngInp.value) : null;
            const rad = radInp && radInp.value ? Math.max(0.2, parseFloat(radInp.value) || 1.5) : 1.5;
            if (clat != null && clng != null && Number.isFinite(clat) && Number.isFinite(clng)) {
              const circLayer = L.circle([clat, clng], {
                radius: rad * 1000,
                color: '#059669',
                fillColor: '#10B981',
                fillOpacity: 0.22,
                weight: 2.6
              }).addTo(lg);
              const centerMarker = L.marker([clat, clng], {
                draggable: canEditRegionShape,
                icon: makeVertexDivIcon(L, true, false),
                zIndexOffset: 1100
              }).addTo(lg);
              if (canEditRegionShape) {
                centerMarker.on('drag', ev => {
                  const ll = ev.target.getLatLng();
                  circLayer.setLatLng(ll);
                  const radNow = radInp && radInp.value !== '' ? Math.max(0.2, parseFloat(radInp.value) || 1.5) : 1.5;
                  setModalGovernorate(resolveGovernorateForCircle(ll.lat, ll.lng, radNow).code);
                });
                centerMarker.on('dragend', ev => {
                  const pos = ev.target.getLatLng();
                  const nLat = round5(pos.lat), nLng = round5(pos.lng);
                  if (cLatInp) cLatInp.value = String(nLat);
                  if (cLngInp) cLngInp.value = String(nLng);
                  if (isMfg && distInp) {
                    const wtcHub = getCompanyHub('WTC', SEED);
                    distInp.value = String(Math.round(roadAdjustedKm(wtcHub.lat, wtcHub.lng, nLat, nLng)));
                  }
                  redraw();
                });
              }
              if (opts.fitBounds) {
                map.setView([clat, clng], rad > 4 ? 11 : 12, { animate: false });
              }
            }
          } else if (zt === 'polygon') {
            const ll = polyPts.map(p => [p[1], p[0]]);
            let polyShape = null;
            if (ll.length >= 3) {
              polyShape = L.polygon(ll, {
                color: polyLocked ? '#059669' : '#2563EB',
                fillColor: polyLocked ? '#10B981' : '#3B82F6',
                fillOpacity: 0.22,
                weight: 2.6
              }).addTo(lg);
            } else if (ll.length === 2) {
              polyShape = L.polyline(ll, { color: '#2563EB', weight: 2.6 }).addTo(lg);
            }

            ll.forEach((ptLatLng, idx) => {
              const isFirst = idx === 0;
              const canClose = canEditRegionShape && isFirst && !polyLocked && polyPts.length >= 3;
              const vm = L.marker(ptLatLng, {
                draggable: canEditRegionShape,
                icon: makeVertexDivIcon(L, isFirst, canClose),
                zIndexOffset: isFirst ? 1200 : 1120
              }).addTo(lg);
              if (canEditRegionShape) {
                vm.on('click', ev => {
                  L.DomEvent.stopPropagation(ev);
                  if (canClose) {
                    polyLocked = true;
                    commitPolyToHiddenFields();
                    redraw();
                  }
                });
                vm.on('drag', ev => {
                  const pos = ev.target.getLatLng();
                  polyPts[idx] = [round5(pos.lng), round5(pos.lat)];
                  if (polyShape) polyShape.setLatLngs(polyPts.map(p => [p[1], p[0]]));
                  setModalGovernorate(resolveGovernorateForPolygonPoints(polyPts).code);
                });
                vm.on('dragend', () => {
                  commitPolyToHiddenFields();
                  redraw();
                });
              }
            });

            if (canEditRegionShape && polyPts.length >= 3) {
              for (let i = 0; i < polyPts.length; i++) {
                if (!polyLocked && i === polyPts.length - 1) continue;
                const a = polyPts[i];
                const b = polyPts[(i + 1) % polyPts.length];
                const midLat = round5((a[1] + b[1]) / 2);
                const midLng = round5((a[0] + b[0]) / 2);
                const mm = L.marker([midLat, midLng], {
                  draggable: true,
                  icon: makeMidpointDivIcon(L),
                  zIndexOffset: 1080
                }).addTo(lg);
                const insertIdx = i + 1;
                mm.on('click', ev => {
                  L.DomEvent.stopPropagation(ev);
                  polyPts.splice(insertIdx, 0, [midLng, midLat]);
                  commitPolyToHiddenFields();
                  redraw();
                });
                mm.on('dragend', ev => {
                  const pos = ev.target.getLatLng();
                  polyPts.splice(insertIdx, 0, [round5(pos.lng), round5(pos.lat)]);
                  commitPolyToHiddenFields();
                  redraw();
                });
              }
            }

            if (opts.fitBounds && polyShape && polyShape.getBounds) {
              try {
                const b = polyShape.getBounds();
                if (b && b.isValid && b.isValid()) map.fitBounds(b, { padding: [24, 24], maxZoom: 13, animate: false });
              } catch (_) {}
            }
          }
          stripLeafletTitles(canvas);
        };

        hydrateRegionFieldsIntoMapState();
        redraw({ fitBounds: true });

        map.on('mousemove', ev => {
          if (!canEditRegionShape) return;
          const zt = (shapeSel && shapeSel.value) || 'boundary';
          if (zt !== 'polygon' || polyLocked || polyPts.length === 0) {
            if (previewLine) {
              try { map.removeLayer(previewLine); } catch (_) {}
              previewLine = null;
            }
            return;
          }
          const last = polyPts[polyPts.length - 1];
          const cur = [ev.latlng.lat, ev.latlng.lng];
          const pts = [[last[1], last[0]], cur];
          if (polyPts.length >= 2) {
            pts.push([polyPts[0][1], polyPts[0][0]]);
          }
          if (previewLine) {
            previewLine.setLatLngs(pts);
          } else {
            previewLine = L.polyline(pts, { color: '#2563EB', weight: 2, dashArray: '5, 5', opacity: 0.72, interactive: false }).addTo(map);
          }
        });

        map.on('click', ev => {
          if (!canEditRegionShape) return;
          closeAllGeoPlaceMenus();
          const lat = round5(ev.latlng.lat), lng = round5(ev.latlng.lng);
          const zt = (shapeSel && shapeSel.value) || 'boundary';
          if (zt === 'circle') {
            if (cLatInp) cLatInp.value = String(lat);
            if (cLngInp) cLngInp.value = String(lng);
            if (gjInp) gjInp.value = '';
            if (getGeoActiveIndustry() === 'Manufacturing' && distInp) {
              const wtcHub = getCompanyHub('WTC', SEED);
              distInp.value = String(Math.round(roadAdjustedKm(wtcHub.lat, wtcHub.lng, lat, lng)));
            }
            redraw();
          } else if (zt === 'polygon') {
            if (polyLocked) return;
            polyPts.push([lng, lat]);
            commitPolyToHiddenFields();
            redraw();
          }
        });
      }).catch(() => {});
    } else {
      cleanupModalGeoMap();
    }
  }

  // ==================== INLINE TICKET ROUTE MINI-MAP (#originMiniMapCanvas) ====================
  const _ticketOriginMini = { map: null, layers: null, canvas: null, lastStamp: '', callbacks: null };

  function cleanupTicketOriginMiniMap() {
    cleanupModalGeoMap();
    if (_ticketOriginMini.map) {
      try { _ticketOriginMini.map.remove(); } catch (_) {}
    }
    _ticketOriginMini.map = null;
    _ticketOriginMini.layers = null;
    _ticketOriginMini.canvas = null;
    _ticketOriginMini.lastStamp = '';
    _ticketOriginMini.callbacks = null;
  }

  function renderTicketOriginMiniLayers(L, SEED, STATE, spec) {
    const map = _ticketOriginMini.map;
    if (!map) return;
    if (_ticketOriginMini.layers) {
      _ticketOriginMini.layers.clearLayers();
    } else {
      _ticketOriginMini.layers = L.layerGroup().addTo(map);
    }
    const lg = _ticketOriginMini.layers;
    hydrateSeedGeo(SEED);

    const regions = ((SEED && SEED.records && SEED.records.regions) || []).filter(r => r && !r.voided);
    regions.forEach(r => {
      if (r.zone_type === 'circle' && r.center_lat != null && r.radius_km > 0) {
        L.circle([Number(r.center_lat), Number(r.center_lng)], {
          radius: Number(r.radius_km) * 1000,
          color: '#0D9488',
          fillColor: '#10B981',
          fillOpacity: 0.08,
          weight: 1.2
        }).addTo(lg);
      } else if (r.zone_geojson) {
        const gj = parseZoneGeoJson(r.zone_geojson);
        if (gj) L.geoJSON(gj, { style: { color: '#2563EB', fillColor: '#3B82F6', fillOpacity: 0.06, weight: 1.1 } }).addTo(lg);
      }
    });

    const fromSpec = spec.fromSpec;
    const toSpec = spec.toSpec;
    const est = (fromSpec && fromSpec.name && toSpec && toSpec.name)
      ? estimateLegKm(fromSpec, toSpec, SEED, {
          skipFuel: true,
          onAsyncRoute: () => {
            _ticketOriginMini.lastStamp = '';
            if (_ticketOriginMini.callbacks && typeof _ticketOriginMini.callbacks.onRouteResolved === 'function') {
              _ticketOriginMini.callbacks.onRouteResolved();
            }
          }
        })
      : null;

    if (est && est.fromCoord && est.toCoord && est.fromCoord.lat != null && est.toCoord.lat != null && est.oneWayKm > 0) {
      renderVerifiedRoutePolylineLayers(L, lg, est, {
        weight: 3.4,
        fallbackColor: '#1D4ED8',
        dashArray: '6, 5',
        halo: true,
        interactive: true
      });
    }

    const siteStats = getUnifiedSiteStats(SEED, STATE);
    const activeFromNorm = fromSpec && fromSpec.type === 'site' ? norm(fromSpec.name) : '';
    const activeToNorm = toSpec && toSpec.type === 'site' ? norm(toSpec.name) : '';
    const sites = ((SEED && SEED.records && SEED.records.sites) || []).filter(s => s && !s.voided && s.latitude != null && s.longitude != null);

    // Show top frequent sites + active origin/destination sites cleanly
    sites.forEach(s => {
      const nk = norm(s.name);
      const isFrom = nk && nk === activeFromNorm;
      const isTo = nk && nk === activeToNorm;
      const st = siteStats.byNorm.get(nk) || { total: 0 };
      if (!isFrom && !isTo && st.total < 80) return;
      const lat = Number(s.latitude), lng = Number(s.longitude);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      const pinColor = isFrom ? '#2563EB' : (isTo ? '#059669' : '#64748B');
      const showLbl = isFrom || isTo;
      const m = L.marker([lat, lng], {
        icon: makeSvgPinIcon(L, pinColor, showLbl ? s.name : '', false),
        zIndexOffset: (isFrom || isTo) ? 750 : 100
      }).addTo(lg);
      if (m.bindTooltip && !showLbl) {
        m.bindTooltip(esc(s.name), { className: 'geo-zone-tooltip', direction: 'top' });
      }
      m.on('click', ev => {
        L.DomEvent.stopPropagation(ev);
        if (_ticketOriginMini.callbacks && typeof _ticketOriginMini.callbacks.onPickSite === 'function') {
          _ticketOriginMini.callbacks.onPickSite(s.name);
        }
      });
    });

    getAllCompanyHubs(SEED).forEach(h => {
      const isActiveBu = Boolean(fromSpec && fromSpec.type === 'bu' && norm(fromSpec.name) === norm(h.name));
      const m = L.marker([h.lat, h.lng], {
        icon: makeSvgPinIcon(L, isActiveBu ? '#059669' : '#D9A54A', isActiveBu ? h.name : '', true),
        zIndexOffset: isActiveBu ? 950 : 850
      }).addTo(lg);
      if (m.bindTooltip && !isActiveBu) {
        m.bindTooltip(`${esc(h.name)} Hub`, { className: 'geo-zone-tooltip', direction: 'top' });
      }
      m.on('click', ev => {
        L.DomEvent.stopPropagation(ev);
        if (_ticketOriginMini.callbacks && typeof _ticketOriginMini.callbacks.onPickBu === 'function') {
          _ticketOriginMini.callbacks.onPickBu(h.name);
        }
      });
    });

    const cFrom = fromSpec ? resolveEndpointCoord(fromSpec, SEED) : null;
    const cTo = toSpec ? resolveEndpointCoord(toSpec, SEED) : null;
    if (cFrom && cFrom.lat != null && cTo && cTo.lat != null && (Math.abs(cFrom.lat - cTo.lat) > 0.0005 || Math.abs(cFrom.lng - cTo.lng) > 0.0005)) {
      const miniPts = [[cFrom.lat, cFrom.lng], [cTo.lat, cTo.lng]];
      if (est && Array.isArray(est.routeCoords) && est.routeCoords.length > 1) {
        est.routeCoords.forEach(pt => {
          if (Array.isArray(pt) && pt.length >= 2 && Number.isFinite(Number(pt[0])) && Number.isFinite(Number(pt[1]))) {
            miniPts.push([Number(pt[1]), Number(pt[0])]);
          }
        });
      }
      const b = L.latLngBounds(miniPts);
      map.fitBounds(b, { padding: [28, 28], maxZoom: 13, animate: false });
    } else if (cFrom && cFrom.lat != null) {
      map.setView([cFrom.lat, cFrom.lng], 11, { animate: false });
    } else {
      map.setView([33.83, 35.50], 10, { animate: false });
    }
  }

  function wireTicketOriginMiniMap(canvasEl, opts = {}) {
    if (!canvasEl) return;
    const { SEED, STATE, fromSpec, toSpec } = opts;
    _ticketOriginMini.callbacks = opts;
    const stamp = `${fromSpec ? fromSpec.type + ':' + norm(fromSpec.name) : ''}|${toSpec ? toSpec.type + ':' + norm(toSpec.name) : ''}|${SEED ? (SEED._customRev || 0) : 0}|${GEO_STORE.updatedAt || ''}`;

    ensureLeaflet().then(L => {
      if (!canvasEl.isConnected) return;
      if (_ticketOriginMini.map && _ticketOriginMini.canvas === canvasEl) {
        if (_ticketOriginMini.lastStamp !== stamp) {
          _ticketOriginMini.lastStamp = stamp;
          renderTicketOriginMiniLayers(L, SEED, STATE, { fromSpec, toSpec });
        }
        setTimeout(() => { try { _ticketOriginMini.map && _ticketOriginMini.map.invalidateSize(); } catch (_) {} }, 25);
        return;
      }
      cleanupTicketOriginMiniMap();
      const map = L.map(canvasEl, { zoomControl: true, attributionControl: false }).setView([33.83, 35.50], 10);
      canvasEl.querySelectorAll('[title]').forEach(el => el.removeAttribute('title'));
      _ticketOriginMini.map = map;
      _ticketOriginMini.canvas = canvasEl;
      _ticketOriginMini.lastStamp = stamp;
      addBaseTiles(L, map);
      renderTicketOriginMiniLayers(L, SEED, STATE, { fromSpec, toSpec });
      setTimeout(() => { try { map.invalidateSize(); } catch (_) {} }, 40);

      map.on('click', ev => {
        const cb = _ticketOriginMini.callbacks;
        if (cb && typeof cb.onClickMapCoord === 'function') {
          cb.onClickMapCoord(round5(ev.latlng.lat), round5(ev.latlng.lng));
        }
      });
    }).catch(() => {});
  }

  function jumpToMapRegionOrSite(opts = {}) {
    STUDIO.collapsed = false;
    STUDIO._userPanned = false;
    STUDIO._jumpPendingTs = Date.now();
    if (opts.region) STUDIO.selectedRegion = opts.region;
    if (opts.site) {
      STUDIO.distTo = `site:${opts.site}`;
      const sites = (window.MFG_SEED && window.MFG_SEED.records && window.MFG_SEED.records.sites) || [];
      const sRow = sites.find(s => s && norm(s.name) === norm(opts.site));
      if (sRow && sRow.region && !opts.region) STUDIO.selectedRegion = sRow.region;
    }
    if (opts.bu) {
      STUDIO.distFrom = `bu:${opts.bu}`;
    }
  }

